821	/// Returns `true` if all references of `binding` are only used as a type.
822	/// If there is no reference, then returns `false`.
823	fn is_only_used_as_type(
824	    model: &SemanticModel,
825	    binding: &JsIdentifierBinding,
826	    references: &EmbeddedValueReferences,
827	) -> bool {
828	    // First check if the binding is used as a value in embedded non-source snippets (templates)
829	    if let Ok(name_token) = binding.name_token()
830	        && references.is_used_as_value(name_token.text_trimmed())
831	    {
832	        return false;
833	    }
834	
835	    // Then check semantic model for type-only usage
836	    let mut result = false;
837	    for reference in binding.all_references(model) {
838	        if let Some(reference) = AnyJsIdentifierUsage::cast_ref(&reference.syntax()) {
839	            result = reference.is_only_type();
840	            if !result {
841	                break;
842	            }
843	        }
844	    }
845	    result
846	}
